/** Modules: the catalog, rarities and merging, substats and upgrade costs. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { heading, infobox, recordTable, sections, table } from '../render.mjs'

export function build(context) {
  const { data } = context.sdk
  const { format } = context
  const modules = data.MODULE_TEMPLATES

  for (const module of modules) {
    const bonuses = module.rarityBonuses ?? []
    context.page(
      `Module: ${module.name}`,
      sections(
        bonuses.length === 0 ? module.description() : (module.baseEffect ?? ''),
        infobox([
          ['Type', module.type],
          ['Initials', module.initials],
          ['Unique', module.unique ? 'Yes' : 'No'],
          ['Lowest rarity', module.minRarity],
          ['Highest rarity', module.maxRarity],
        ]),
        bonuses.length > 0 ? heading(2, 'Effect By Rarity') : '',
        bonuses.length > 0
          ? table(['Rarity', 'Value', 'Effect'], bonuses.map(bonus => [bonus.rarity, format.value(bonus.value), module.description(bonus.value)]))
          : '',
        `Back to ${context.link('Modules')}.`,
      ),
      { source: 'MODULE_TEMPLATES' },
    )
  }

  const types = [...new Set(modules.map(module => module.type))]
  context.page(
    'Modules',
    sections(
      context.overview('modules'),
      ...types.map(type =>
        sections(
          heading(2, `${type} Modules`),
          table(
            ['Module', 'Initials', 'Unique', 'Rarity range'],
            modules
              .filter(module => module.type === type)
              .map(module => [
                context.link(`Module: ${module.name}`, module.name),
                module.initials,
                module.unique ? 'Yes' : 'No',
                module.minRarity === module.maxRarity ? module.minRarity : `${module.minRarity} to ${module.maxRarity}`,
              ]),
          ),
        ),
      ),
      `See also ${context.link('Module Rarities and Merging')}, ${context.link('Module Substats')} and ${context.link('Module Upgrade Costs')}.`,
    ),
    { source: 'MODULE_TEMPLATES' },
  )

  context.page(
    'Module Rarities and Merging',
    sections(
      heading(2, 'Level Cap By Rarity'),
      table(['Rarity', 'Level cap'], Object.entries(data.MODULE_RARITY_LEVEL_CAPS)),
      heading(2, 'How Far A Module Can Be Merged'),
      table(['Drawn at', 'Can reach'], Object.entries(data.MODULE_MERGE_CEILING_BY_DRAWN_RARITY)),
      heading(2, 'Merge Recipes'),
      recordTable(data.MODULE_MERGE_RECIPES, format),
      infobox([
        ['Maximum copies of one module', data.MODULE_MAX_COPIES],
        ['Maximum Ancestral stars', data.MODULE_MAX_ANCESTRAL_STARS],
        ['Inventory cap', data.MODULE_INVENTORY_CAP],
        ['Highest module level', data.ABSOLUTE_MAX_MODULE_LEVEL],
      ]),
      `Back to ${context.link('Modules')}.`,
    ),
    { source: ['MODULE_RARITY_LEVEL_CAPS', 'MODULE_MERGE_CEILING_BY_DRAWN_RARITY', 'MODULE_MERGE_RECIPES'] },
  )

  const rarities = data.MODULE_SUBSTAT_BASE_RARITIES
  context.page(
    'Module Substats',
    sections(
      ...Object.values(data.MODULE_SUBSTAT_CANONICAL_DATA).map(group =>
        sections(
          heading(2, group.title),
          table(['Substat', ...rarities], group.substats.map(substat => [substat.label, ...rarities.map(rarity => substat.valuesByRarity[rarity])])),
        ),
      ),
      heading(2, 'Reroll Cost'),
      table(
        ['Locked substats', 'Cost'],
        data.MODULE_REROLL_COSTS_BY_LOCKED_SUBSTATS.map((cost, locked) => [locked, format.cost(cost)]),
      ),
      `Back to ${context.link('Modules')}.`,
    ),
    { source: ['MODULE_SUBSTAT_CANONICAL_DATA', 'MODULE_REROLL_COSTS_BY_LOCKED_SUBSTATS'] },
  )

  context.page(
    'Module Upgrade Costs',
    sections(
      `The ${data.MODULE_COIN_COSTS.length} upgrade steps of a module, in order, with what each costs.`,
      table(
        ['Upgrade', 'Coins', 'Shards'],
        data.MODULE_COIN_COSTS.map((coins, index) => [index + 1, format.cost(coins), format.cost(data.MODULE_SHARD_COSTS[index])]),
      ),
      `Back to ${context.link('Modules')}.`,
    ),
    { source: ['MODULE_COIN_COSTS', 'MODULE_SHARD_COSTS'] },
  )

  context.group('Modules', ['Modules', 'Module Rarities and Merging', 'Module Substats', 'Module Upgrade Costs'])
}
